#pragma once
#include "Json.h"
#include "core/Decoder.h"
#include "analysis/Analysis.h"
namespace spdif::json {
inline std::string layout(const SampleLayout& l){return Object().integer("bits",l.bits).boolean("known",l.known).boolean("stereo",l.stereo).boolean("professional",l.professional).str();}
inline std::string record(const Subframe& f){
 auto o=event("subframe");o.sample("start_sample",f.start).sample("end_sample_inclusive",f.end).integer("channel",f.channel).text("preamble",std::string(1,f.preamble)).integer("raw_slots_4_31",f.raw).signed_integer("signed_container_24",f.sample).boolean("V_invalid",f.validity).boolean("U",f.user).boolean("C",f.status).boolean("P",f.parity).boolean("parity_ok",f.parity_ok).signed_integer("block_position",f.block_position).number("sample_rate_hz",f.sample_rate).text("content",content_name(f.content)).raw("layout",layout(f.layout));
 std::vector<std::string> b;for(auto value:f.field_boundaries)b.push_back(quote(std::to_string(value)));o.raw("field_boundaries",array(b));return o.str();
}
inline std::string record(const StatusBlock& b){auto info=status_info(b.c);auto o=event("channel_status");o.sample("start_sample",b.start).sample("end_sample_inclusive",b.end).integer("channel",b.channel).boolean("integrity",b.integrity).text("C_hex",hex(b.c)).text("U_hex",hex(b.u)).text("interpretation",b.interpretation).raw("layout",layout(info.layout)).integer("declared_sample_rate_hz",info.sample_rate).boolean("supported",info.supported).boolean("non_audio",info.non_audio).integer("channel_mode",info.channel_mode);return o.str();}
inline std::string record(const Diagnostic& d){return event("diagnostic").sample("start_sample",d.start).sample("end_sample_inclusive",d.end).text("code",d.code).text("message",d.message).str();}
inline std::string record(const ContentInfo& c){return event("content").sample("start_sample",c.start).sample("end_sample_inclusive",c.end).text("format",content_name(c.format)).text("evidence",c.evidence).integer("Pc",c.pc).integer("Pd",c.pd).boolean("burst",c.burst).boolean("complete",c.complete).boolean("integrity",c.integrity).str();}
inline std::string channel_health(const ChannelHealth& c){return Object().integer("decoded_subframes",c.decoded_subframes).sample("decoded_coverage_samples",c.decoded_coverage_samples).sample("unknown_coverage_samples",c.unknown_coverage_samples).integer("parity_failures",c.parity_failures).integer("V_invalid",c.v_invalid).integer("sync_losses",c.sync_losses).integer("status_good",c.status_good).integer("status_damaged",c.status_damaged).boolean("has_fault",c.has_fault).sample("first_fault_sample",c.first_fault).sample("last_fault_sample",c.last_fault).integer("rate_measurements",c.rate_measurements).number("mean_sample_rate_hz",c.mean_sample_rate).number("min_sample_rate_hz",c.min_sample_rate).number("max_sample_rate_hz",c.max_sample_rate).str();}
inline std::string health_fields(Object o,const HealthWindow& h){std::vector<std::string> channels;for(const auto& c:h.channels)channels.push_back(channel_health(c));return o.sample("start_sample",h.start).sample("end_sample_exclusive",h.end).sample("decoded_stream_samples",h.decoded_stream_samples).sample("unknown_stream_samples",h.unknown_stream_samples).integer("sync_losses",h.sync_losses).integer("late_events",h.late_events).raw("channels",array(channels)).str();}
inline std::string record(const HealthWindow& h){return health_fields(event("health_window"),h);}
inline std::string record(const StatusChange& s){std::vector<std::string> fields;for(const auto& f:s.fields)fields.push_back(Object().text("name",f.name).text("old",f.old_value).text("new",f.new_value).str());return event("status_change").integer("channel",s.channel).sample("previous_start_sample",s.previous_start).sample("previous_end_sample_exclusive",s.previous_end).sample("start_sample",s.start).sample("end_sample_exclusive",s.end).text("old_C_hex",hex(s.previous)).text("new_C_hex",hex(s.current)).text("changed_mask_hex",hex(s.changed_mask)).raw("fields",array(fields)).str();}
inline std::string record(const PcmWindow& p){return event("pcm_window").integer("channel",p.channel).integer("bits",p.bits).boolean("layout_override",p.layout_override).sample("window_start_sample",p.window_start).sample("window_end_sample_exclusive",p.window_end).sample("start_sample",p.start).sample("end_sample_exclusive",p.end).integer("segment",p.segment).integer("accepted",p.accepted).integer("excluded_parity",p.excluded_parity).integer("excluded_invalid",p.excluded_invalid).integer("excluded_unknown",p.excluded_unknown).integer("excluded_non_pcm",p.excluded_non_pcm).integer("excluded_layout",p.excluded_layout).signed_integer("minimum",p.minimum).signed_integer("maximum",p.maximum).integer("peak",p.peak).number("mean",p.mean).number("rms",p.rms).number("peak_normalized",p.peak_normalized).number("rms_normalized",p.rms_normalized).integer("silence_samples",p.silence_samples).number("silence_seconds",p.silence_seconds).integer("full_scale_samples",p.full_scale_samples).integer("full_scale_runs",p.full_scale_runs).integer("max_full_scale_run",p.max_full_scale_run).str();}
}
